    "REQ-F-22": {
      "statement": "The system shall allow order staff to decline an order whose status is pending by setting its status to closed."
    },
    "REQ-F-23": {
      "statement": "The system shall reject an attempt to decline an order if the status of the order is not pending, and shall leave the status unchanged."
    },
    "REQ-F-24": {
      "statement": "The system shall reject a request to raise an invoice for an order that has been declined."
