    "REQ-F-25": {
      "statement": "The system shall allow order staff to set the status of an order to shipped when its status is filled."
    },
    "REQ-F-26": {
      "statement": "The system shall reject an attempt to set an order to shipped if the status of the order is not filled, and shall leave the status unchanged."
