    "REQ-F-35": {
      "statement": "The system shall allow an accountant to confirm a payment whose status is pending by setting its status to completed."
    },
    "REQ-F-36": {
      "statement": "When an accountant confirms a pending payment against an invoice whose status is issued, the system shall set the status of that invoice to paid."
    },
    "REQ-F-37": {
      "statement": "The system shall leave the status of the order billed by an invoice unchanged when a payment against that invoice is confirmed."
    },
    "REQ-F-38": {
      "statement": "The system shall allow an accountant to reject a payment whose status is pending by setting its status to failed, and shall leave the status of its invoice and of its order unchanged."
    },
    "REQ-F-39": {
      "statement": "The system shall reject an attempt to confirm or to reject a payment whose status is not pending, and shall leave the status unchanged."
    },
    "REQ-F-40": {
      "statement": "The system shall allow order staff to close an order whose status is shipped and whose invoice has the status paid, by setting its status to closed."
    },
    "REQ-F-41": {
      "statement": "The system shall reject an attempt to close an order whose status is shipped if its invoice does not have the status paid, and shall leave the status unchanged."
    },
    "REQ-F-42": {
      "statement": "The system shall reject an attempt to close an order whose invoice has the status paid if the status of the order is not shipped, and shall leave the status unchanged."
    },
    "REQ-F-43": {
      "statement": "The system shall close a filled order only after both the shipping of the order and the settlement of its invoice have completed, whichever of the two finishes last."
    },
    "REQ-F-44": {
      "statement": "The system shall not change the status of an order whose status is closed."
    },
    "REQ-F-45": {
      "statement": "The system shall treat every attribute as mandatory, except the bank account of a customer, and shall reject a customer record or a product record in which a mandatory attribute is absent."
    },
    "REQ-F-46": {
      "statement": "The system shall represent monetary values (product price, unit price, order total, invoice amount, payment amount) as decimal numbers."
    },
    "REQ-F-47": {
      "statement": "The system shall restrict the status of an order to submitted, pending, filled, shipped or closed; of an invoice to issued or paid; and of a payment to pending, completed or failed."
    },
    "REQ-F-48": {
      "statement": "The system shall restrict the payment method recorded on an order, on an invoice and on a payment to bank, card or cash."
    },
    "REQ-F-49": {
      "statement": "The system shall change the status of an order only from submitted to pending, from pending to filled or to closed, from filled to shipped, and from shipped to closed."
    },
    "REQ-F-50": {
      "statement": "The system shall change the status of an invoice only from issued to paid, and the status of a payment only from pending to completed or to failed."
    }
  },
  "NFR_INPUT": {
    "REQ-N-01": {
      "statement": "When a user submits an order containing up to 50 order items under normal operating conditions, the system shall register the order and respond within 2 seconds for at least 95% of submissions."
    },
    "REQ-N-02": {
      "statement": "Under normal operating conditions, the system shall support at least 200 concurrent users and at least 20 order submissions per second while meeting the response time of REQ-N-01."
    },
    "REQ-N-03": {
      "statement": "The system shall be available for at least 99.5% of each calendar month, excluding scheduled maintenance announced at least 24 hours in advance."
    },
    "REQ-N-04": {
      "statement": "When a server failure occurs, the system shall resume accepting requests within 15 minutes without losing any order, invoice or payment recorded before the failure."
    },
    "REQ-N-05": {
      "statement": "The system shall authenticate every user before granting access to any customer, order, invoice or payment data, and shall reject 100% of unauthenticated requests."
